        $fields=[];foreach(['problem'=>1200,'location'=>255,'attempted_action'=>1200,'observed_behaviour'=>1800,'expected_behaviour'=>1200]as$key=>$max){$fields[$key]=ops_post_string($key,$max);if($fields[$key]==='')throw new RuntimeException('Please complete every problem-description field.');}
        $route=mb_substr((string)($_POST['route']??''),0,500);$title=mb_substr($fields['problem'],0,90);$s=db()->prepare("INSERT INTO system_issues(reporter_employee_id,title,problem,location,attempted_action,observed_behaviour,expected_behaviour,route,internal_status) VALUES(?,?,?,?,?,?,?,?,'ai_processing')");$s->execute([$employeeId,$title,$fields['problem'],$fields['location'],$fields['attempted_action'],$fields['observed_behaviour'],$fields['expected_behaviour'],$route]);$id=(int)db()->lastInsertId();$key=system_issue_generate_key($id);system_issue_uploads($id,$employeeId);system_issue_event($id,'reported',null,'ai_processing','Employee submitted a system issue.');system_issue_notify(['title'=>'System issue received','message'=>$key.' was saved and is being reviewed.','action_link'=>BASE_URL.'/apps/operations/system-issues.php?issue='.$id],[$employeeId]);$result=system_issue_triage($id);si_redirect((string)($result['message']??'Problem reported successfully.'),'success','?issue='.$id);
    }
    $id=max(1,(int)($_POST['issue_id']??0));$issue=ops_rows('SELECT * FROM system_issues WHERE id=?',[$id])[0]??null;if(!$issue||(!$owner&&(int)$issue['reporter_employee_id']!==$employeeId))throw new RuntimeException('Issue not found.');
    if($action==='add_information'){$message=ops_post_string('message',2000);if($message==='')throw new RuntimeException('Enter the requested information.');system_issue_uploads($id,$employeeId);system_issue_event($id,'employee_information_added',$issue['internal_status'],'ai_processing',$message);db()->prepare("UPDATE system_issues SET internal_status='ai_processing',employee_status='under_review' WHERE id=?")->execute([$id]);system_issue_triage($id);si_redirect('Information sent for review.','success','?issue='.$id);}
    if($action==='join_duplicate'){$duplicate=max(1,(int)($_POST['duplicate_id']??0));$target=ops_rows('SELECT * FROM system_issues WHERE id=? AND duplicate_of_id IS NULL',[$duplicate])[0]??null;if(!$target)throw new RuntimeException('The original issue is unavailable.');db()->prepare("UPDATE system_issues SET duplicate_of_id=?,internal_status='duplicate',employee_status='under_review' WHERE id=?")->execute([$duplicate,$id]);db()->prepare('UPDATE system_issues SET affected_count=affected_count+1 WHERE id=?')->execute([$duplicate]);system_issue_event($id,'joined_duplicate',$issue['internal_status'],'duplicate','Joined '.$target['issue_key'].'.',['duplicate_of'=>$duplicate]);si_redirect('You joined '.$target['issue_key'].' as an affected employee.','success','?issue='.$duplicate);}
