'Invalid status.');$verified=$to==='done'?$integration['live_verified_at']:$issue['verified_at'];db()->prepare('UPDATE system_issues SET internal_status=?,employee_status=?,verified_at=?,verified_by=? WHERE id=?')->execute([$internal,$employee,$verified,$to==='done'?$employeeId:$issue['verified_by'],$id]);system_issue_event($id,'status_changed',$issue['internal_status'],$internal,'Owner updated the controlled workflow.');system_issue_notify(['title'=>'System issue '.$employee,'message'=>$issue['issue_key'].' is now '.system_issue_status_label($employee).'.','action_link'=>BASE_URL.'/apps/operations/system-issues.php?issue='.$id],[(int)$issue['reporter_employee_id']]);si_redirect('Issue status updated.','success','?issue='.$id);}
