$where=$owner?'1=1':'(i.reporter_employee_id=? OR i.id IN (SELECT duplicate_of_id FROM system_issues WHERE reporter_employee_id=?))';$params=$owner?[]:[$employeeId,$employeeId];$issues=ops_rows("SELECT i.*,e.full_name reporter_name,(SELECT COUNT(*) FROM system_issue_attachments a WHERE a.issue_id=i.id) attachment_count FROM system_issues i LEFT JOIN ops_employees e ON e.id=i.reporter_employee_id WHERE $where ORDER BY FIELD(i.internal_status,'new','ai_processing','needs_information','brief_ready','codex_queued','codex_running','pr_open','testing','deployed','verified','done','deferred','duplicate'),i.updated_at DESC",$params);$selectedId=max(0,(int)($_GET['issue']??0));$selected=null;foreach($issues as$row)if((int)$row['id']===$selectedId)$selected=$row;
